"""RFC 7386 JSON Merge Patch for PATCH /profiles/{id}.

Storage: SQLite, `profiles` table with a JSON `profile` column containing a
document that includes a nested `settings` object.

Merge-patch semantics (RFC 7386):
  * null in the patch removes the key from the target
  * objects merge recursively
  * arrays (and all other non-object values) replace wholesale
"""

import sqlite3

from flask import Flask, g, jsonify, request

DATABASE = "profiles.db"

app = Flask(__name__)


# --------------------------------------------------------------------------
# Merge Patch (RFC 7386, section 4)
# --------------------------------------------------------------------------

def merge_patch(target, patch):
    """Apply a JSON merge patch document to a target JSON value."""
    if not isinstance(patch, dict):
        # Non-object patch: replace wholesale (covers arrays too).
        return patch

    if not isinstance(target, dict):
        target = {}

    for key, value in patch.items():
        if value is None:
            # null removes the key.
            target.pop(key, None)
        else:
            target[key] = merge_patch(target.get(key), value)

    return target


# --------------------------------------------------------------------------
# SQLite plumbing
# --------------------------------------------------------------------------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(app.config["DATABASE"])
        g.db.row_factory = sqlite3.Row
        g.db.execute(
            """
            CREATE TABLE IF NOT EXISTS profiles (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                profile TEXT NOT NULL  -- JSON document
            )
            """
        )
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


# --------------------------------------------------------------------------
# Routes
# --------------------------------------------------------------------------

@app.post("/profiles")
def create_profile():
    doc = request.get_json(silent=True)
    if doc is None or not isinstance(doc, dict):
        return jsonify(error="request body must be a JSON object"), 400
    db = get_db()
    cur = db.execute("INSERT INTO profiles (profile) VALUES (?)", (jsonify_doc(doc),))
    db.commit()
    row = db.execute("SELECT profile FROM profiles WHERE id = ?", (cur.lastrowid,)).fetchone()
    return jsonify(id=cur.lastrowid, **__import__("json").loads(row["profile"])), 201


@app.get("/profiles/<int:profile_id>")
def get_profile(profile_id):
    row = _fetch(profile_id)
    if row is None:
        return jsonify(error="profile not found"), 404
    import json

    return jsonify(id=profile_id, **json.loads(row["profile"]))


@app.patch("/profiles/<int:profile_id>")
def patch_profile(profile_id):
    row = _fetch(profile_id)
    if row is None:
        return jsonify(error="profile not found"), 404

    patch = request.get_json(silent=True)
    if not isinstance(patch, dict):
        return jsonify(error="merge patch must be a JSON object"), 400

    import json

    current = json.loads(row["profile"])
    updated = merge_patch(current, patch)

    db = get_db()
    db.execute(
        "UPDATE profiles SET profile = ? WHERE id = ?",
        (jsonify_doc(updated), profile_id),
    )
    db.commit()

    return jsonify(id=profile_id, **updated)


def _fetch(profile_id):
    return get_db().execute(
        "SELECT profile FROM profiles WHERE id = ?", (profile_id,)
    ).fetchone()


def jsonify_doc(doc):
    """Canonical JSON serialization for storage."""
    import json

    return json.dumps(doc, separators=(",", ":"), sort_keys=True)


if __name__ == "__main__":
    app.run(debug=True)

